/**
 * Runtime helpers for code generated by the immutaby plugin.
 *
 * Every helper takes the root last and returns the (possibly new) root. Taking
 * the root last means it is read after the right-hand side has run, so writes
 * nested inside the right-hand side are not lost.
 */

type Key = PropertyKey;
// State is arbitrary user data; the helpers index into it dynamically.
type Node = any;

/** A path segment that is resolved at runtime, e.g. `s.todos.find(p)` → the index of the match. */
class Finder {
  readonly method: "findIndex" | "findLastIndex";
  readonly predicate: (value: unknown, index: number, array: unknown[]) => unknown;

  constructor(method: Finder["method"], predicate: Finder["predicate"]) {
    this.method = method;
    this.predicate = predicate;
  }
}

type Path = (Key | Finder)[];

/**
 * State for one `mut:` block: the set of nodes copied within the block, plus
 * slots the generated code reads expression results from.
 */
export interface Context {
  copies: Set<object>;
  /** Result of the last helper, for writes used as expressions. */
  value: unknown;
  /** Previous numeric value, for postfix `++` / `--`. */
  previous: unknown;
  /** Path of a compound assignment, so it is evaluated only once. */
  path: Path;
}

/** Classes marked with this symbol are copied like plain objects (same symbol as immer's `immerable`). */
export const immerable: unique symbol = Symbol.for("immer-draftable") as never;

export function createContext(): Context {
  return { copies: new Set(), value: undefined, previous: undefined, path: [] };
}

export function finder(method: Finder["method"], predicate: Finder["predicate"]): Finder {
  return new Finder(method, predicate);
}

function isDraftable(value: object): boolean {
  const proto = Object.getPrototypeOf(value);
  return proto === null || immerable in value || Boolean(proto.constructor?.[immerable]);
}

function shallowCopy(value: Node): Node {
  if (Array.isArray(value)) return value.slice();
  if (value instanceof Map) return new Map(value);
  if (value instanceof Set) return new Set(value);
  if (Object.getPrototypeOf(value) === Object.prototype) return { ...value };
  if (isDraftable(value)) return Object.assign(Object.create(Object.getPrototypeOf(value)), value);
  // Not draftable: shared, and writes go straight through (as in immer).
  return value;
}

/** The copy of `value` owned by this block, made at most once. Primitives pass through. */
function owned(context: Context, value: Node): Node {
  if (value === null || typeof value !== "object" || context.copies.has(value)) return value;
  const copy = shallowCopy(value);
  context.copies.add(copy);
  return copy;
}

/**
 * Copies `root` (already owned) down the first `depth` keys of `path`, linking
 * each copy into its parent. Returns the owned node at that depth. The path
 * must already be resolved by `get`.
 */
function ownPath(context: Context, root: Node, path: Path, depth: number): Node {
  let node = root;
  for (let i = 0; i < depth; i++) {
    const key = path[i] as Key;
    const child = node[key];
    const copy = owned(context, child);
    if (copy !== child) node[key] = copy;
    node = copy;
  }
  return node;
}

/** Reads `root` at `path` (or its first `depth` keys), resolving finders in `path` in place. */
export function get(root: Node, path: Path, depth = path.length): Node {
  let node = root;
  for (let i = 0; i < depth; i++) {
    const segment = path[i];
    const key: Key = segment instanceof Finder ? (path[i] = node[segment.method](segment.predicate) as number) : segment;
    node = node[key];
  }
  return node;
}

/** Resolves the finders in `path` once, so it can be kept as an alias. */
export function resolve(path: Path, root: Node): Path {
  get(root, path);
  return path;
}

/** `root.path = value`. */
export function set(context: Context, path: Path, value: unknown, root: Node): Node {
  context.value = value;
  const last = path.length - 1;
  const parent = get(root, path, last);
  const key = path[last] as Key;
  const unchanged = Object.is(parent[key], value) && (value !== undefined || key in parent);
  if (unchanged) return root;

  root = owned(context, root);
  ownPath(context, root, path, last)[key] = value;
  return root;
}

/** `root.path++` / `root.path--`, with `delta` of 1 or -1. */
export function increment(context: Context, path: Path, delta: 1 | -1, root: Node): Node {
  const current = get(root, path);
  const previous = typeof current === "bigint" ? current : Number(current);
  context.previous = previous;
  const next = typeof previous === "bigint" ? previous + BigInt(delta) : previous + delta;
  return set(context, path, next, root);
}

/** `delete root.path`. */
export function remove(context: Context, path: Path, root: Node): Node {
  context.value = true;
  const last = path.length - 1;
  const key = path[last] as Key;
  if (!(key in get(root, path, last))) return root;

  root = owned(context, root);
  delete ownPath(context, root, path, last)[key];
  return root;
}

const MUTATING_ARRAY_METHODS = new Set<Key>(["push", "pop", "shift", "unshift", "splice", "sort", "reverse", "fill", "copyWithin"]);

/** Whether calling `method` with `args` on `target` would change it. */
function mutates(target: Node, method: Key, args: unknown[]): boolean {
  if (Array.isArray(target)) return MUTATING_ARRAY_METHODS.has(method);

  if (target instanceof Map) {
    if (method === "set") return !(target.has(args[0]) && Object.is(target.get(args[0]), args[1]));
    if (method === "delete") return target.has(args[0]);
    if (method === "clear") return target.size > 0;
  }

  if (target instanceof Set) {
    if (method === "add") return !target.has(args[0]);
    if (method === "delete") return target.has(args[0]);
    if (method === "clear") return target.size > 0;
  }

  return false;
}

/** `root.path.method(...args)` for a method that may mutate its receiver. */
export function callMethod(context: Context, path: Path, method: Key, args: unknown[], root: Node): Node {
  let target = get(root, path);
  if (mutates(target, method, args)) {
    root = owned(context, root);
    target = ownPath(context, root, path, path.length);
  }
  context.value = target[method](...args);
  return root;
}

function stateArray(root: Node, path: Path, what: string): unknown[] {
  const list = get(root, path);
  if (!Array.isArray(list)) throw new TypeError(`mut: ${what} over state supports arrays only`);
  return list;
}

/** `for (const item of root.path)` where `item` is written through: yields the path of each element. */
export function* each(getRoot: () => Node, path: Path): Generator<Path> {
  stateArray(getRoot(), path, "for...of");
  for (let i = 0; i < get(getRoot(), path).length; i++) yield [...path, i];
}

/** `root.path.method(callback, ...rest)` where the callback writes through its element: it receives element paths. */
export function iterate(path: Path, method: string, args: unknown[], root: Node): unknown {
  const list = stateArray(root, path, method) as Node;
  const [callback, ...rest] = args as [(...a: unknown[]) => unknown, ...unknown[]];
  const at = (index: number): Path => [...path, index];
  const wrapped =
    method === "reduce" || method === "reduceRight"
      ? (acc: unknown, _value: unknown, index: number, array: unknown) => callback(acc, at(index), index, array)
      : (_value: unknown, index: number, array: unknown) => callback(at(index), index, array);
  return list[method](wrapped, ...rest);
}
